changeSet.sql:
-- Сначала создаём колонки, если нет
ALTER TABLE users ADD COLUMN IF NOT EXISTS is_admin BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE users ADD COLUMN IF NOT EXISTS is_deleted BOOLEAN DEFAULT FALSE NOT NULL;

-- Дропаем старый constraint
ALTER TABLE users DROP CONSTRAINT IF EXISTS chk_users_role;

-- Конвертируем все варианты ролей в title case:
-- 'Admin'  -> 'Editor' (и ставим is_admin=true)
-- 'ADMIN'  -> 'Editor' (и ставим is_admin=true)
-- 'EDITOR' -> 'Editor'
-- 'READER' -> 'Reader'
-- 'GUEST'  -> 'Guest'
UPDATE users SET is_admin = TRUE WHERE role IN ('Admin', 'ADMIN');
UPDATE users SET role = 'Editor' WHERE role IN ('Admin', 'ADMIN', 'EDITOR');
UPDATE users SET role = 'Reader' WHERE role IN ('Reader', 'READER');
UPDATE users SET role = 'Guest' WHERE role IN ('Guest', 'GUEST');

-- Теперь создаём новый constraint с title case
ALTER TABLE users ADD CONSTRAINT chk_users_role CHECK (role IN ('Guest', 'Reader', 'Editor'));

-- Индекс
DROP INDEX IF EXISTS idx_users_not_deleted;
CREATE INDEX idx_users_not_deleted ON users (id) WHERE is_deleted = false;

rollback.sql:
UPDATE users SET role = 'Admin' WHERE is_admin = true;
UPDATE users SET role = 'Editor' WHERE is_admin = false AND role = 'Editor';
ALTER TABLE users DROP CONSTRAINT IF EXISTS chk_users_role;
ALTER TABLE users
    ADD CONSTRAINT chk_users_role
        CHECK (role IN ('Admin', 'Editor', 'Reader'));
